CREATE OR ALTER PROCEDURE [dbo].[uspBotConfiguration_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @IntegrationChannelId UNIQUEIDENTIFIER = NULL
	, @BotStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[IntegrationChannelId]
			, t.[BotCode]
			, t.[BotName]
			, t.[BotUsername]
			, t.[TargetAudience]
			, t.[WebhookPath]
			, t.[BotStatus]
			, t.[LastTokenRotatedAt]
			, t.[SecretReference]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[BotConfiguration] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[BotCode] LIKE CONCAT('%', @SearchText, '%') OR t.[BotName] LIKE CONCAT('%', @SearchText, '%'))
			AND (@IntegrationChannelId IS NULL OR t.[IntegrationChannelId] = @IntegrationChannelId)
			AND (ISNULL(@BotStatus, '') = '' OR t.[BotStatus] = @BotStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'integrationChannelId' THEN r.[IntegrationChannelId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'integrationChannelId' THEN r.[IntegrationChannelId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'botCode' THEN r.[BotCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'botCode' THEN r.[BotCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'botName' THEN r.[BotName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'botName' THEN r.[BotName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'botUsername' THEN r.[BotUsername] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'botUsername' THEN r.[BotUsername] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'targetAudience' THEN r.[TargetAudience] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'targetAudience' THEN r.[TargetAudience] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'webhookPath' THEN r.[WebhookPath] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'webhookPath' THEN r.[WebhookPath] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'botStatus' THEN r.[BotStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'botStatus' THEN r.[BotStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lastTokenRotatedAt' THEN r.[LastTokenRotatedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lastTokenRotatedAt' THEN r.[LastTokenRotatedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'secretReference' THEN r.[SecretReference] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'secretReference' THEN r.[SecretReference] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
